const $=id=>document.getElementById(id),canvas=$('scene');
const gl=canvas.getContext('webgl',{antialias:true,preserveDrawingBuffer:true});
function colorCSS(g){return 'rgb('+colors[g].map(v=>Math.round(v*255)).join(',')+')';}
const colors={RTEN:[.27,.83,.76],ATEN:[1,.60,.31],coronet:[.77,.53,.95],pr:[.95,.77,.31],MN:[.45,.68,1],MGIN:[.95,.40,.57],AMG:[.62,.76,.35],ACIN:[.35,.64,.77],BTN:[.89,.64,.74],'その他':[.64,.72,.81]};
