function showWhole(){expressionMode='morphology';expressionLegend();filter='全細胞';$('search').value='';shown=new Set(cells.map((c,i)=>i));selected.clear();$('context').checked=false;update();fit(shown);document.querySelectorAll('#groups button').forEach(b=>b.classList.toggle('active',b.textContent==='全細胞'));}
function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;}
let prog,loc;
const gpu=new Map(),pending=new Set(),failed=new Set(),queue=[];let active=0,bytes=0,saveTimer;
function network(){if($('network'))$('network').textContent=failed.size?`読込失敗 ${failed.size}件。「読込を再試行」で再接続できます。`:active||queue.length?`全体を構築中 ${[...shown].filter(i=>gpu.has(i)).length} / ${shown.size} · 受信 ${(bytes/1e6).toFixed(1)} MB`:`読込完了 ${[...shown].filter(i=>gpu.has(i)).length} / ${shown.size} · ${(bytes/1e6).toFixed(1)} MB`;}
function requestMesh(i){if(pending.has(i)||failed.has(i))return;pending.add(i);queue.push(i);pump();}
async function pump(){if(active>=2||!queue.length)return;let i=queue.shift();if(!shown.has(i)){pending.delete(i);pump();return;}active++;network();try{
let c=cells[i],r=await fetch(c.file);if(!r.ok)throw Error('HTTP '+r.status);
let zipped=await r.arrayBuffer();bytes+=zipped.byteLength;
if(!('DecompressionStream' in window))throw Error('このブラウザーは圧縮読込に未対応です');
let raw=await new Response(new Blob([zipped]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
if(raw.byteLength!==c.rawBytes)throw Error('サイズ不一致');
let hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw)),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==c.sha256)throw Error('データ検証失敗');
let h=new DataView(raw),nv=h.getUint32(0,true),ni=h.getUint32(4,true);if(nv+ni+8!==raw.byteLength)throw Error('形式不一致');
// Keep only visible meshes plus a small buffer cache; never alter their geometry.
for(const [k,b]of gpu)if(!shown.has(k)){gl.deleteBuffer(b.v);gl.deleteBuffer(b.e);gpu.delete(k);}
let v=gl.createBuffer(),e=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,v);gl.bufferData(gl.ARRAY_BUFFER,new Uint8Array(raw,8,nv),gl.STATIC_DRAW);gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,e);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint8Array(raw,8+nv,ni),gl.STATIC_DRAW);
if(gl.getError()!==gl.NO_ERROR){gl.deleteBuffer(v);gl.deleteBuffer(e);throw Error('描画メモリ不足。表示する細胞を減らしてください');}gpu.set(i,{v,e});
}catch(e){failed.add(i);console.error(cells[i].name,e);}finally{active--;pending.delete(i);network();draw();pump();}}
function saveView(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{let view={cells:[...shown].map(i=>cells[i].name),selected:[...selected].map(i=>cells[i].name),yaw,pitch,zoom,pan,center,radius,context:$('context').checked,marker:expressionMode,markerCandidates:$('expression-candidates').checked,rnaCandidates,expressionOnly:$('expression-auto-only').checked};history.replaceState(null,'','#'+encodeURIComponent(JSON.stringify(view)));},350);}
function restoreView(){try{if(!location.hash)return;let v=JSON.parse(decodeURIComponent(location.hash.slice(1)));if(!Array.isArray(v.cells))return;let ids=names=>new Set(cells.map((c,i)=>names.includes(c.name)?i:-1).filter(i=>i>=0));shown=ids(v.cells);expressionMode=markerModes.includes(v.marker)?v.marker:'morphology';$('expression-candidates').checked=!!v.markerCandidates;rnaCandidates=!!v.rnaCandidates;$('rna-candidates').checked=rnaCandidates;$('expression-auto-only').checked=v.expressionOnly!==false;expressionLegend();$('context').checked=!!v.context;selected=ids(Array.isArray(v.selected)?v.selected:[]);if([v.yaw,v.pitch,v.zoom,v.radius,...v.pan,...v.center].every(Number.isFinite)&&v.radius>0&&v.zoom>0){yaw=v.yaw;pitch=v.pitch;zoom=v.zoom;radius=v.radius;pan=v.pan;center=v.center;}}catch(e){console.warn('表示リンクを読み込めません',e);}}
$('share').onclick=async()=>{saveView();await new Promise(r=>setTimeout(r,400));try{await navigator.clipboard.writeText(location.href);$('share').textContent='リンクをコピーしました';setTimeout(()=>$('share').textContent='この表示のリンク',2000);}catch{prompt('このURLをコピーしてください',location.href);}};
$('retry').onclick=()=>{failed.clear();draw();};
$('menu').onclick=()=>document.body.classList.toggle('panel-open');$('closemenu').onclick=()=>document.body.classList.remove('panel-open');

function initGL(){if(!gl)throw Error('WebGLが無効です。Chromeのグラフィックアクセラレーションを確認してください。');if(!gl.getExtension('OES_element_index_uint'))throw Error('32bit indexが非対応です');prog=gl.createProgram();gl.attachShader(prog,shader(gl.VERTEX_SHADER,`attribute vec3 aPos;attribute vec3 aNormal;uniform vec3 uCenter;uniform float uRadius,uZoom,uAspect;uniform vec2 uPan;uniform mat3 uRot;varying vec3 vN;void main(){vec3 p=uRot*((aPos-uCenter)/uRadius);gl_Position=vec4(p.x*uZoom/uAspect+uPan.x,p.y*uZoom+uPan.y,-p.z/12.0,1.0);vN=uRot*aNormal;}`));gl.attachShader(prog,shader(gl.FRAGMENT_SHADER,`precision mediump float;uniform vec3 uColor;uniform float uAlpha,uPick;varying vec3 vN;void main(){float light=.38+.62*abs(dot(normalize(vN),normalize(vec3(.3,.5,1.))));gl_FragColor=vec4(uColor*mix(light,1.,uPick),uAlpha);}`));gl.linkProgram(prog);if(!gl.getProgramParameter(prog,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(prog));gl.useProgram(prog);loc={};for(const n of ['uCenter','uRadius','uZoom','uAspect','uPan','uRot','uColor','uAlpha','uPick'])loc[n]=gl.getUniformLocation(prog,n);buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);for(const [name,offset]of [['aPos',0],['aNormal',12]]){let a=gl.getAttribLocation(prog,name);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,3,gl.FLOAT,false,24,offset);}gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);pickFB=gl.createFramebuffer();pickTex=gl.createTexture();pickDepth=gl.createRenderbuffer();}
function resize(){let d=Math.min(devicePixelRatio,2),w=Math.round(canvas.clientWidth*d),h=Math.round(canvas.clientHeight*d);if(w===canvas.width&&h===canvas.height)return;canvas.width=w;canvas.height=h;gl.bindTexture(gl.TEXTURE_2D,pickTex);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,w,h,0,gl.RGBA,gl.UNSIGNED_BYTE,null);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.NEAREST);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.NEAREST);gl.bindRenderbuffer(gl.RENDERBUFFER,pickDepth);gl.renderbufferStorage(gl.RENDERBUFFER,gl.DEPTH_COMPONENT16,w,h);gl.bindFramebuffer(gl.FRAMEBUFFER,pickFB);gl.framebufferTexture2D(gl.FRAMEBUFFER,gl.COLOR_ATTACHMENT0,gl.TEXTURE_2D,pickTex,0);gl.framebufferRenderbuffer(gl.FRAMEBUFFER,gl.DEPTH_ATTACHMENT,gl.RENDERBUFFER,pickDepth);gl.bindFramebuffer(gl.FRAMEBUFFER,null);}
function uniforms(pick){let cy=Math.cos(yaw),sy=Math.sin(yaw),cx=Math.cos(pitch),sx=Math.sin(pitch);rotation=new Float32Array([cy,sx*sy,-cx*sy,0,cx,sx,sy,-sx*cy,cx*cy]);gl.uniformMatrix3fv(loc.uRot,false,rotation);gl.uniform3fv(loc.uCenter,center);gl.uniform1f(loc.uRadius,radius);gl.uniform1f(loc.uZoom,zoom*Math.min(1,canvas.width/canvas.height));gl.uniform1f(loc.uAspect,canvas.width/canvas.height);gl.uniform2fv(loc.uPan,pan);gl.uniform1f(loc.uPick,pick?1:0);}
function mesh(i,pick,ghost){let c=cells[i];if(!gpu.has(i)){requestMesh(i);return;}let b=gpu.get(i);gl.bindBuffer(gl.ARRAY_BUFFER,b.v);gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,b.e);for(const [n,o]of [["aPos",0],["aNormal",12]]){let a=gl.getAttribLocation(prog,n);gl.vertexAttribPointer(a,3,gl.FLOAT,false,24,o);}let col=pick?[(i+1&255)/255,((i+1>>8)&255)/255,0]:atlasCellColor(c);gl.uniform3fv(loc.uColor,col);gl.uniform1f(loc.uAlpha,ghost?.055:1);gl.drawElements(gl.TRIANGLES,c.count,gl.UNSIGNED_INT,0);}
let framePending=false;function draw(pick=false){if(!ready)return;if(!pick){if(framePending)return;framePending=true;requestAnimationFrame(()=>{framePending=false;render(false);});return;}render(true);}function render(pick=false){if(!ready)return;if(!pick)saveView();resize();gl.bindFramebuffer(gl.FRAMEBUFFER,pick?pickFB:null);gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(pick?0:.055,pick?0:.079,pick?0:.115,1);gl.depthMask(true);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);uniforms(pick);if(!pick)updateOrientation();const contextual=!pick&&$('context').checked&&selected.size>0;if(contextual){gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.depthMask(false);for(const i of shown)if(!selected.has(i))mesh(i,false,true);gl.disable(gl.BLEND);gl.depthMask(true);for(const i of shown)if(selected.has(i))mesh(i,false,false);}else{gl.disable(gl.BLEND);for(const i of shown)mesh(i,pick,false);}gl.bindFramebuffer(gl.FRAMEBUFFER,null);}
function bounds(ids){let min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];for(const i of ids)for(let j=0;j<3;j++){min[j]=Math.min(min[j],cells[i].min[j]);max[j]=Math.max(max[j],cells[i].max[j]);}return {min,max};}
function fit(ids){if(!ids.size)return;let {min,max}=bounds(ids);center=min.map((v,j)=>(v+max[j])/2);radius=Math.hypot(...max.map((v,j)=>(v-min[j])/2))||1;zoom=.86;pan=[0,0];draw();}
function select(i,multi){multi=multi||$("multi").checked;if(!multi)selected.clear();if(multi&&selected.has(i))selected.delete(i);else selected.add(i);shown.add(i);update();draw();}
function updateBase(){network();let q=$('search').value.toLowerCase(),visible=cells.map((c,i)=>({...c,i})).filter(c=>(filter==='全細胞'||filter===c.group)&&(c.name+' '+c.group+' '+(c.group==='BPIN'?'PBIN':'')).toLowerCase().includes(q));$('list').replaceChildren();for(const c of visible){let row=document.createElement('div');row.className='cell'+(selected.has(c.i)?' selected':'');let check=document.createElement('input');check.type='checkbox';check.checked=shown.has(c.i);check.setAttribute('aria-label',c.name+'を表示');check.onchange=()=>{if(check.checked){shown.add(c.i);failed.delete(c.i);}else shown.delete(c.i);update();draw();};check.onclick=e=>e.stopPropagation();let dot=document.createElement('i');dot.className='dot';dot.style.background=`rgb(${atlasCellColor(c).map(v=>Math.round(v*255)).join(',')})`;let name=document.createElement('span');name.textContent=c.name+(c.name.match(/^\d+$/)&&c.group!=='その他'?' · '+c.group:'');let focus=document.createElement('button');focus.textContent='寄る';focus.setAttribute('aria-label',c.name+'にズーム');focus.onclick=e=>{e.stopPropagation();select(c.i,false);fit(selected);};row.append(check,dot,name,focus);row.onclick=e=>select(c.i,e.ctrlKey||e.metaKey);$('list').appendChild(row);}$('count').textContent=`検索 ${visible.length} / 全 ${cells.length} · 表示 ${shown.size}`;$('summary').textContent=`${shown.size} meshes · ${selected.size} selected`;
 $('classsource').replaceChildren();if(selected.size===1){let c=cells[[...selected][0]];if(c.classificationSource&&c.classificationSource.startsWith('http')){let a=document.createElement('a');a.href=c.classificationSource;a.target='_blank';a.rel='noopener';a.textContent='分類の出典';$('classsource').append(a,document.createTextNode(' '+c.classificationNote));}}if(selected.size){let names=[...selected].map(i=>cells[i].name);$('name').textContent=names.length===1?names[0]+' · '+cells[[...selected][0]].group:`${names.length}細胞を選択`;let n=[...selected].reduce((sum,i)=>sum+cells[i].count/3,0);$('info').textContent=(names.some(n=>n.startsWith('pns'))?'RTENの再構成範囲内の軸索・終末です。細胞全体や細胞体の配置を示すものではありません。 ':'')+[...selected].map(i=>cells[i].name+' ['+cells[i].group+']').join(', ')+` / ${n.toLocaleString()} 面。high res原座標・面を保持（空間的な間引きなし）。`;}else{$('name').textContent='全体・色分け表示';$('info').textContent='色は細胞群を表します。形態をクリックして名前を確認できます。RTENは軸索・終末の再構成範囲で、細胞体の位置ではありません。';}}
function pick(e){draw(true);gl.bindFramebuffer(gl.FRAMEBUFFER,pickFB);let r=canvas.getBoundingClientRect(),pixel=new Uint8Array(4);gl.readPixels(Math.floor((e.clientX-r.left)*canvas.width/r.width),Math.floor((r.bottom-e.clientY)*canvas.height/r.height),1,1,gl.RGBA,gl.UNSIGNED_BYTE,pixel);gl.bindFramebuffer(gl.FRAMEBUFFER,null);let id=pixel[0]+256*pixel[1]-1;if(id>=0&&id<cells.length)select(id,e.ctrlKey||e.metaKey);draw();}
const touches=new Map();let gesture=null,moved=false;
function pair(){let a=[...touches.values()];return {x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2,d:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)};}
canvas.onpointerdown=e=>{touches.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture(e.pointerId);if(touches.size===1){drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,pan:e.button===2||e.shiftKey};moved=false;}else{gesture=pair();moved=true;}};
canvas.onpointermove=e=>{if(!touches.has(e.pointerId)||!ready)return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size>=2){let n=pair();if(gesture){zoom=Math.min(100,Math.max(.05,zoom*n.d/Math.max(gesture.d,1)));pan[0]+=2*(n.x-gesture.x)/canvas.clientWidth;pan[1]-=2*(n.y-gesture.y)/canvas.clientHeight;}gesture=n;moved=true;}else if(drag){let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4)moved=true;if(drag.pan){pan[0]+=2*dx/canvas.clientWidth;pan[1]-=2*dy/canvas.clientHeight;}else{yaw+=dx*.008;pitch+=dy*.008;}drag.x=e.clientX;drag.y=e.clientY;}draw();};
