const annotationEvidence=[
 {ids:['ATEN1','ATEN2','ATEN3','ATEN4'],marker:'GNRH2',title:'GnRH2 → aATEN群',text:'Okawa et al. 2020 Fig. 2a：21 hpfのaATENでgnrh2とvGluTレポーターの重なりを6/6幼生に報告。各ATEN番号・左右別の発現量ではありません。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC7596717/'},
 {ids:['MGIN2L','MGIN2R'],marker:'GABRD',title:'GABA_A δサブユニット（Gabrd）→ MGIN2',text:'Gabrd（KH.C1.1254）のMGIN2での転写産物濃縮とin situによる発現確認が報告されています。MGIN2という細胞型の報告を左右の形態に対応づけています。左右別の定量、他のGABA_Aサブユニット、機能的受容体や使用するプロモーター断片の発現範囲を確定するものではありません。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC6987015/'},
 {ids:['AMG1','AMG2','AMG3','AMG4','AMG6','AMG7'],marker:'RNA19',title:'RNA cluster 19 → 抑制性AMG群',text:'Kourakis et al. 2026は統合scRNA-seqのcluster 19をVGAT・Otp・Lhx1/5とASIC/HLH-2レポーターで抑制性AMG群に対応づけています。群レベルの対応で、AMG番号別のRNA値ではありません。現在の33群のRNA表とは別の再解析であり、PC2/vGluT検出率はまだ移していません。AMG5は対象外です。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC13509005/'},
 {ids:['AMG6','AMG7'],marker:'Lhx1/5',title:'Lhx1/5 in situ → AMG6・7',text:'VGATとの二重in situと位置に基づく対応。AMG以外にも発現するため、Lhx1/5だけでこの2細胞とは確定できません。プロモーター断片による標識範囲は別途確認が必要です。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC13509005/'},
 {ids:['AMG2','AMG3','AMG4'],marker:'Otp',title:'Otp in situ → AMG2・3・4',text:'VGATとの二重in situと位置に基づく対応。AMG以外にも発現します。RNA cluster 19内のLhx1/5陽性群とOtp陽性群は分離されておらず、各番号の検出率にはできません。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC13509005/'},
 {ids:['78'],marker:'VGAT',title:'vGAT → fb2 / cor-assBVIN78',text:'Chung et al. 2023：VGAT in situの3D位置合わせと細胞体・軸索形態からfb2を78に対応。レポーター像との比較があり、単なるRNA群名の推定とは異なります。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC10528541/'},
 {ids:['AMG1','AMG2','AMG3','AMG4','AMG6','AMG7'],marker:'VGAT',title:'vGAT → 抑制性AMG 6細胞',text:'VGAT>KaedeによるAMG1–4,6–7の標識報告。AMG5は含めません。従来の取り込み表で0となる形態も、この別の文献証拠を表示します。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC11185728/'},
 {ids:['ACIN1L','ACIN2L','ACIN2R'],marker:'VGAT',title:'vGAT → ACIN群',text:'ACIN群でVGAT発現が報告されています。Atlasにある3形態を対応させていますが、この3DパッケージにはACIN1Rがありません。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC11419600/'},
 {ids:['ddNL','ddNR'],marker:'Dmbx',title:'Dmbxレポーター → ddN左右対',text:'Dmbx>GFPはddN標識に使用されています。A12.239 / ddNという系譜・形態名を照合できます。RNA表のMGクラスターへの割り当ては別途必要です。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC6987015/'},
 {ids:['MGIN1L','MGIN1R','MGIN2L','MGIN2R'],marker:'Vsx',title:'Vsxレポーター → MGIN1/2候補',text:'Vsx>GFPはMGIN2に加えてMGIN1にも発現し、背側表皮正中線での弱い標識も報告されています。Vsx陽性だけでMGIN2とは確定できません。',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC6987015/'}
];
