function initLiteratureIdTable(panel){
 const details=document.createElement('details');details.id='literature-id-panel';
 const title=document.createElement('summary');title.textContent='GABA作動性・vGAT：細胞群と個別IDの対応一覧';details.append(title);
 const note=document.createElement('p');note.className='hint';note.textContent='個別ID＝160などのEM再構築ID（MN1Lのような名前付きIDも含む）。文献によるIDへの陽性予測と、scRNA-seqクラスターへの対応は別々です。VGATはGABA／グリシン輸送体なので、VGATだけで両者を区別はできません。PBV-PNIN（160/162/163/164）とBPIN（90/92）は別群です。';details.append(note);
 const search=document.createElement('input');search.id='literature-id-search';search.type='search';search.placeholder='ID・論文分類を検索：160、PBV、PNIN…';search.setAttribute('aria-label','文献の細胞ID・分類検索');details.append(search);
 const label=document.createElement('label'),positive=document.createElement('input');positive.id='literature-positive';positive.type='checkbox';positive.checked=true;label.append(positive,document.createTextNode('陽性予測・報告のあるIDだけ'));details.append(label);
 const status=document.createElement('p');status.id='literature-id-count';details.append(status);
 const table=document.createElement('table');table.id='literature-id-table';details.append(table);
 function render(){
  table.replaceChildren();const head=document.createElement('tr');for(const text of ['ID / 論文分類','VGATの根拠','3D']){const th=document.createElement('th');th.textContent=text;head.append(th);}table.append(head);
  const rows=expressionEvidence.vgatTable.map(r=>({...r}));
  for(const e of annotationEvidence.filter(e=>e.marker==='VGAT'))for(const id of e.ids)if(!rows.some(r=>r.id===id))rows.push({id,type:cells.find(c=>c.name===id)?.group||'文献補足',vgat:null});
  const q=(search.value||'').toLowerCase();let count=0;
  for(const r of rows){const extra=annotationEvidence.filter(e=>e.marker==='VGAT'&&e.ids.includes(r.id)),isPositive=r.vgat==='+'||extra.length>0;
   if(positive.checked&&!isPositive||!(r.id+' '+r.type).toLowerCase().includes(q))continue;count++;
   const tr=document.createElement('tr'),name=document.createElement('td'),ev=document.createElement('td'),action=document.createElement('td');name.textContent=r.id+' / '+r.type;
   ev.textContent=r.vgat===null?'原表の行なし':r.vgat==='+'?'Table 1：＋（ID対応の陽性予測）':'Table 1：0（陰性確定ではない）';
   for(const e of extra)ev.append(document.createTextNode(' / '),Object.assign(document.createElement('a'),{href:e.url,target:'_blank',rel:'noopener',textContent:e.title}));
   const i=cells.findIndex(c=>c.name===r.id),b=document.createElement('button');b.textContent=i<0?'形態なし':'このIDを見る';b.disabled=i<0;b.onclick=()=>{expressionMode='VGAT';filter='全細胞';$('search').value='';shown=new Set([i]);selected=new Set([i]);$('context').checked=false;expressionLegend();update();fit(shown);draw();};action.append(b);tr.append(name,ev,action);table.append(tr);
  }status.textContent=count+' ID（原表全'+expressionEvidence.vgatTable.length+'行＋補足文献。形態のないIDも掲載）';
 }search.oninput=render;positive.onchange=render;render();
 const source=document.createElement('a');source.href='https://pmc.ncbi.nlm.nih.gov/articles/PMC11419600/#t1';source.target='_blank';source.rel='noopener';source.textContent='Borba et al. 2024 Table 1：全行の出典';details.append(source);
 details.className='rna-results';panel.append(details);
}
